'use strict';
const C=Capacity,$=id=>document.getElementById(id);
const iconPaths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',chart:'M3 3v18h18M6 15l5-5 4 3 6-8',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',database:'M3 5c0-4 18-4 18 0s-18 4-18 0v14c0 4 18 4 18 0V5M3 12c0 4 18 4 18 0',layers:'M2 7l10-5 10 5-10 5zM2 12l10 5 10-5M2 17l10 5 10-5',play:'M8 4l13 8-13 8z',external:'M14 3h7v7M21 3L11 13M10 3H3v18h18v-7',download:'M12 3v12m-5-5 5 5 5-5M3 15v6h18v-6',upload:'M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6',reset:'M3 11a9 9 0 1 1 2 7M3 4v7h7',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M16 8l-3 5-5 3 3-5z',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 11v6M12 7v1',monitor:'M2 3h20v14H2zM8 22h8M12 17v5',folder:'M2 6h8l2 3h10v12H2zM2 6V3h7l3 3h10v3',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6',server:'M3 3h18v7H3zM3 14h18v7H3zM6 6h1M6 17h1M15 6h3M15 17h3'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.grid}"/></svg>`}
function icons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=(n,d=1)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const bytes=n=>n>=1e9?f(n/1e9,2)+' GB':n>=1e6?f(n/1e6,2)+' MB':n>=1000?f(n/1000,1)+' KB':n+' B';
let servers=C.makeDemo(),selected=servers[0].id,horizon=120,view='overview',warning=80,critical=90,acknowledged=new Set(),tourStep=0;
const current=()=>servers.find(s=>s.id===selected)||servers[0];
function status(util){return util>=critical?'critical':util>=warning?'warning':'healthy'}
function days(n){return n===null?'No crossing':n===0?'Reached':`${n} days`}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4500)}
function switchView(name){view=name;document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!=='view-'+name);document.querySelectorAll('nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('pageName').textContent={overview:'Overview',planning:'Capacity planner',alerts:'Alert center',data:'Data & collection',model:'Model lab'}[name];renderView();window.scrollTo({top:0,behavior:'smooth'})}
function setServer(id){selected=id;for(const name of ['plannerServer','ledgerServer','modelServer'])$(name).value=id;render()}
function updateSelects(){for(const name of ['plannerServer','ledgerServer','modelServer']){$(name).innerHTML=servers.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');$(name).value=selected}}
function spark(s){const ps=s.points.slice(-30),lo=Math.min(...ps.map(p=>p.used))-4,hi=Math.max(...ps.map(p=>p.used))+4;const pts=ps.map((p,i)=>`${i/(ps.length-1)*90},${30-(p.used-lo)/(hi-lo)*26}`).join(' ');return `<svg class="sparkline" viewBox="0 0 90 34" aria-hidden="true"><polyline points="${pts}" fill="none" stroke="${s.color}" stroke-width="1.5"/></svg>`}
function alerts(){const list=[];for(const s of servers){const a=C.analyze(s);for(const [threshold,level] of [[critical,'critical'],[warning,'warning']]){const n=C.runway(s,threshold);if(n===0){if(level==='warning'&&a.utilization>=critical)continue;list.push({id:`${s.id}-${level}-measured`,server:s,level,source:'MEASURED',days:0,title:`${s.name} is above ${threshold}% capacity`,detail:`Latest observation: ${f(a.utilization)}% utilized · threshold ${threshold}%`})}else if(n!==null&&n<=120){list.push({id:`${s.id}-${level}-forecast`,server:s,level,source:'FORECAST',days:n,title:`${s.name} reaches ${threshold}% in ${n} days`,detail:`${f(C.fit(s.points).slope,2)} GB/day fitted growth · if the trend continues`})}}}return list.sort((a,b)=>a.days-b.days||(a.level==='critical'?-1:1))}
function alertHTML(a,full=false){return `<div class="alertrow"><i class="alertdot ${a.level}"></i><div class="alerttext">${esc(a.title)}<small>${esc(a.detail)}</small></div><span class="source">${a.source}</span>${full?`<button class="dismiss" data-ack="${a.id}">${acknowledged.has(a.id)?'Acknowledged ✓':'Acknowledge'}</button>`:''}</div>`}
function render(){const total=servers.reduce((n,s)=>n+s.points.length,0),demo=servers.every(s=>s.source==='Synthetic');$('fleetSummary').textContent=`${servers.length} servers monitored`;$('recordSummary').textContent=`${total} historical observations`;$('datasetBadge').innerHTML=`<i></i> ${demo?'DEMO DATA':'IMPORTED DATA'}`;$('footerSource').textContent=demo?'Synthetic demonstration':'Imported telemetry';$('sourceNote').textContent=demo?'Synthetic workload · model recalculates in your browser':'User-supplied telemetry · processed locally in browser';$('advanceBtn').disabled=!demo;$('replayInfo').textContent=demo?'Demo simulation only · original history is recoverable':'Simulation is disabled for imported measurements';$('fleet').innerHTML=servers.map(s=>{const a=C.analyze(s),st=status(a.utilization);return `<button class="servercard ${s.id===selected?'active':''}" data-server="${s.id}" aria-pressed="${s.id===selected}"><div class="serverhead"><span class="servericon">${icon('server')}</span>${esc(s.name)}<span class="badge ${st}">${st.toUpperCase()}</span></div><div class="servermiddle"><div class="serverused">${f(a.utilization)}<small>%</small></div>${spark(s)}</div><div class="serverbar"><i style="width:${Math.min(100,a.utilization)}%;background:${s.color}"></i></div><div class="serverfoot"><span><b>${f(a.last.used,0)}</b> / ${f(s.capacity,0)} GB</span><span>${days(C.runway(s,critical))} to ${critical}%</span></div></button>`}).join('');document.querySelectorAll('[data-server]').forEach(b=>b.onclick=()=>setServer(b.dataset.server));const list=alerts();$('alertCount').textContent=list.length;$('navAlertCount').textContent=list.length;$('miniAlerts').innerHTML=list.slice(0,3).map(a=>alertHTML(a)).join('')||'<p>No threshold crossings within 120 days.</p>';$('selectedName').textContent=current().name;$('selectedRole').textContent=current().role;$('modelSamples').textContent=current().points.length;const s=current(),d=C.runway(s,critical);$('actionTitle').textContent=d!==null&&d<=30?'A little foresight. A lot less pressure.':'Room today. A plan for tomorrow.';$('actionText').textContent=`${s.name} is growing by ${f(C.fit(s.points).slope,2)} GB/day. Explore an expansion or reclaim scenario before the next threshold.`;$('actionDays').textContent=d===null?'∞':d;$('actionDays').nextElementSibling.firstChild.textContent=`days until ${critical}%`;$('actionFoot').textContent=s.source==='Synthetic'?'Transparent model · synthetic observations':'Transparent model · imported observations';renderView();}
function renderView(){if(view==='overview')drawChart();if(view==='planning')renderPlan();if(view==='alerts')renderAlerts();if(view==='data')renderLedger();if(view==='model')renderModel()}
function drawChart(){const s=current(),m=C.fit(s.points),last=s.points.at(-1),first=s.points[0].day,span=last.day-first+horizon;let offset=Math.min(horizon,+$('scrubber').value);$('scrubber').max=horizon;$('scrubber').value=offset;const maxY=Math.max(s.capacity*1.12,C.forecastValue(s,horizon)+C.interval(m,last.day+horizon)),x=d=>55+(d-first)/span*810,y=v=>242-v/maxY*213;const end=last.day+horizon,nowX=x(last.day);let out=`<defs><linearGradient id="observedFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#99a9d0" stop-opacity=".13"/><stop offset="1" stop-color="#99a9d0" stop-opacity="0"/></linearGradient></defs><rect x="${nowX}" y="20" width="${865-nowX}" height="222" fill="#ffb454" opacity=".025"/>`;
for(let i=0;i<=4;i++){const v=maxY*i/4;out+=`<line x1="55" y1="${y(v)}" x2="865" y2="${y(v)}" stroke="#2a3346" stroke-dasharray="2 5"/><text x="44" y="${y(v)+4}" fill="#657590" font-size="12" text-anchor="end">${f(v,0)}</text>`}
for(const [p,color] of [[100,'#56637b'],[critical,'#ce7180'],[warning,'#ae895b']]){out+=`<line x1="55" y1="${y(s.capacity*p/100)}" x2="865" y2="${y(s.capacity*p/100)}" stroke="${color}" opacity=".65" stroke-dasharray="5 5"/><text x="875" y="${y(s.capacity*p/100)+3}" fill="${color}" font-size="11">${p===100?'LIMIT':p+'%'}</text>`}
const observations=s.points.map(p=>`${x(p.day)},${y(p.used)}`).join(' ');out+=`<polygon points="55,242 ${observations} ${nowX},242" fill="url(#observedFill)"/><polyline points="${observations}" fill="none" stroke="#c3cde1" stroke-width="2"/>`;
const future=Array.from({length:61},(_,i)=>{const d=horizon*i/60;return {day:last.day+d,used:C.forecastValue(s,d),band:C.interval(m,last.day+d)}});const upper=future.map(p=>`${x(p.day)},${y(p.used+p.band)}`).join(' '),lower=[...future].reverse().map(p=>`${x(p.day)},${y(Math.max(0,p.used-p.band))}`).join(' ');out+=`<polygon points="${upper} ${lower}" fill="#ffb454" opacity=".1"/><polyline points="${future.map(p=>`${x(p.day)},${y(p.used)}`).join(' ')}" fill="none" stroke="#ffb454" stroke-width="2" stroke-dasharray="6 5"/><line x1="${nowX}" y1="20" x2="${nowX}" y2="242" stroke="#4a5973" stroke-dasharray="3 4"/><rect x="${nowX-20}" y="3" width="40" height="17" rx="3" fill="#2b3548"/><text x="${nowX}" y="14" text-anchor="middle" fill="#9aaecf" font-size="11">LATEST</text>`;
const point=C.forecastValue(s,offset),px=x(last.day+offset),py=y(point);out+=`<line x1="${px}" y1="25" x2="${px}" y2="242" stroke="#e8b46c" opacity=".3"/><circle cx="${px}" cy="${py}" r="5" fill="#191d28" stroke="#ffc173" stroke-width="2"/>`;
for(let i=0;i<=5;i++){const d=first+span*i/5;out+=`<text x="${x(d)}" y="267" fill="#647691" font-size="12" text-anchor="middle">Day ${f(d,0)}</text>`}
$('chart').innerHTML=out;$('scrubValue').innerHTML=`Day ${f(last.day+offset,0)} <span>→</span> ${f(point)} GB`;$('scrubStatus').textContent=point>s.capacity?'OVER CAPACITY':status(point/s.capacity*100).toUpperCase();$('scrubStatus').className='badge '+status(point/s.capacity*100);$('chart').onpointermove=e=>{const box=$('chart').getBoundingClientRect(),ratio=(e.clientX-box.left)/box.width,day=first+Math.max(0,Math.min(1,(ratio*930-55)/810))*span;let val,kind;if(day<=last.day){const p=s.points.reduce((a,b)=>Math.abs(a.day-day)<Math.abs(b.day-day)?a:b);val=p.used;kind='Observed'}else{val=C.forecastValue(s,day-last.day);kind='Forecast'}$('chartTooltip').textContent=`${kind} · Day ${f(day,0)} · ${f(val)} GB`;$('chartTooltip').hidden=false};$('chart').onpointerleave=()=>$('chartTooltip').hidden=true;}
function scenario(){return {add:+$('addCapacity').value,reclaim:+$('reclaimSpace').value,factor:+$('growthFactor').value}}
function renderPlan(){const s=current(),a=scenario();$('reclaimSpace').max=Math.floor(s.points.at(-1).used/10)*10;if(a.reclaim>s.points.at(-1).used){$('reclaimSpace').value=0;a.reclaim=0}$('capacityValue').textContent=f(a.add,0)+' GB';$('reclaimValue').textContent=f(a.reclaim,0)+' GB';$('factorValue').textContent=f(a.factor)+'×';const before=C.runway(s,90),after=C.runway(s,90,s.capacity+a.add,a.reclaim,a.factor);$('beforeDays').textContent=days(before);$('afterDays').textContent=days(after);const future=C.forecastValue(s,90),scenarioFuture=C.forecastValue(s,90,a.factor,a.reclaim);$('planBars').innerHTML=[['Current trajectory',future,s.capacity,'#ffb454'],['Your scenario',scenarioFuture,s.capacity+a.add,'#4ac8b0']].map(([label,used,cap,color])=>`<div class="planbar"><label>${label} · day +90<span>${f(used/cap*100)}% / ${f(cap,0)} GB</span></label><div><i style="width:${Math.min(100,Math.max(0,used/cap*100))}%;background:${color}"></i></div></div>`).join('');const required=Math.ceil(Math.max(0,future/.8-s.capacity));$('planRecommendation').textContent=`At the fitted growth rate, ${s.name} needs ${f(required,0)} GB of additional capacity to remain at or below 80% utilization 90 days from now. Your scenario projects ${f(scenarioFuture/(s.capacity+a.add)*100)}% utilization at that point.`;}
function renderAlerts(){$('warningValue').textContent=warning+'%';$('criticalValue').textContent=critical+'%';$('allAlerts').innerHTML=alerts().map(a=>alertHTML(a,true)).join('')||'<p>No alerts within the 120-day horizon.</p>';document.querySelectorAll('[data-ack]').forEach(b=>b.onclick=()=>{const key=b.dataset.ack;acknowledged.has(key)?acknowledged.delete(key):acknowledged.add(key);renderAlerts()})}
function renderLedger(){const s=current(),all=s.points,last=all.slice(-12);$('ledgerRows').innerHTML=last.map((p,i)=>{const prev=all[all.length-last.length+i-1];return `<tr><td>${f(p.day,4)}</td><td>${f(p.used,2)}</td><td>${f(s.capacity-p.used,2)}</td><td>${f(p.used/s.capacity*100,2)}%</td><td>${prev?f(p.used-prev.used,2):'—'}</td><td><span class="badge neutral">${esc(s.source)}</span></td></tr>`}).join('');$('ledgerFoot').textContent=`Latest ${last.length} of ${all.length} observations · GB uses decimal units · import remains in browser memory.`}
function renderModel(){const s=current(),a=C.analyze(s),v=a.validation;$('modelMetrics').innerHTML=[['TEST MAE',v?f(v.mae,2)+' GB':'N/A','Mean absolute error'],['TEST RMSE',v?f(v.rmse,2)+' GB':'N/A','Penalizes larger errors'],['TRAIN R²',v?f(v.r2,4):'N/A','Fit on training observations'],['NAIVE BASELINE MAE',v?f(v.baselineMAE,2)+' GB':'N/A','Last training value held constant']].map(([label,value,help])=>`<article class="panel"><label>${label}</label><strong>${value}</strong><small>${help}</small></article>`).join('');$('splitChart').innerHTML=v?`<div class="splitbar"><i style="width:${v.train/s.points.length*100}%"></i><i style="flex:1"></i></div><div class="splitlabels"><span>TRAIN / ${v.train} observations</span><span>TEST / ${v.test} observations</span></div>`:'<p>At least 10 observations are required for held-out evaluation.</p>';$('equation').textContent=`used = ${f(a.model.intercept,2)} + ${f(a.model.slope,4)} × day`;$('modelExplanation').textContent=`Full-history OLS fit: ${f(a.model.slope,3)} GB/day. The plotted forecast uses the latest observed ${f(a.last.used,2)} GB as its starting value and this fitted slope. Test metrics above come from the earlier training-only fit, not the full-history fit.`;}
function download(name,content,type='text/plain'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function ask(question){$('question').value=question;const response=C.advise(servers,question,selected);if(response.error){$('advisorResult').innerHTML=`<p class="answer">${esc(response.error)}</p>`;return}const r=response.result;let answer='';if(response.name==='compare_servers')answer=r.map((v,i)=>`${i+1}. <b>${esc(v.server)}</b> — ${days(v.days)} to ${v.threshold}%`).join('<br>');if(response.name==='forecast_threshold')answer=`<b>${esc(r.server)}</b>: ${days(r.days)} to ${r.threshold}% at ${f(r.growthGB,2)} GB/day fitted growth.`;if(response.name==='plan_capacity')answer=`Add at least <b>${f(r.additionalGB,0)} GB</b> to ${esc(r.server)} to keep projected utilization at or below ${r.target}% after ${r.horizon} days. Projected demand: ${f(r.projectedGB)} GB.`;if(response.name==='evaluate_model')answer=r.mae===undefined?'Not enough observations for a chronological holdout. Import at least 10.':`<b>${esc(r.server)}</b> was evaluated on ${r.test} later observations after training on ${r.train}. MAE: <b>${f(r.mae,2)} GB</b>; RMSE: ${f(r.rmse,2)} GB; naive baseline MAE: ${f(r.baselineMAE,2)} GB.`;$('advisorResult').innerHTML=`<div class="answer">${answer}</div><details class="tooltrace" open><summary>✓ ${response.name}() · executed locally</summary><pre>${esc(JSON.stringify({function:response.name,arguments:response.args,result:response.result},null,2))}</pre></details><p class="help">Rule-based question routing. Numeric results come from the forecast engine. Dataset: ${esc(current().source)}.</p>`;}
const tour=[['Start with the fleet','Three lab servers have different storage trajectories. Select Atlas, Nova and Vault to show how utilization and runway vary. The initial workload is explicitly synthetic.','overview'],['Show the forecast moving','Drag the forecast inspector. The dashed line is projected demand; the shaded region is an approximate prediction interval. Then simulate a day and watch values recompute.','overview'],['Turn a warning into a plan','Add 250 GB or vary growth in the capacity planner. Compare the before-and-after runway to 90%. These are what-if scenarios, not infrastructure changes.','planning'],['Show the evidence','Open Model lab and explain the chronological train/test split. MAE is the average test error in GB. A high synthetic-data score is not real-world validation.','model'],['Finish with real data','In Data & collection, import the collector CSV or inspect a folder. Finally ask the advisor which server needs attention first, then expand its actual tool-call result.','data']];
function showTour(){const [title,text,page]=tour[tourStep];switchView(page);$('tourStepLabel').textContent=`DEMO / ${String(tourStep+1).padStart(2,'0')} OF 05`;$('tourTitle').textContent=title;$('tourText').textContent=text;$('tourBack').disabled=tourStep===0;$('tourNext').textContent=tourStep===4?'Finish walkthrough ✓':'Next →';if(!$('tourDialog').open)$('tourDialog').showModal()}
icons();updateSelects();document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>switchView(b.dataset.goto));document.querySelectorAll('[data-horizon]').forEach(b=>b.onclick=()=>{horizon=+b.dataset.horizon;document.querySelectorAll('[data-horizon]').forEach(x=>x.classList.toggle('selected',x===b));drawChart()});$('scrubber').oninput=drawChart;for(const name of ['plannerServer','ledgerServer','modelServer'])$(name).onchange=e=>setServer(e.target.value);for(const name of ['addCapacity','reclaimSpace','growthFactor'])$(name).oninput=renderPlan;$('resetScenario').onclick=()=>{$('addCapacity').value=0;$('reclaimSpace').value=0;$('growthFactor').value=1;renderPlan()};$('warningThreshold').oninput=e=>{warning=+e.target.value;if(warning>=critical){critical=warning+1;$('criticalThreshold').value=critical}render()};$('criticalThreshold').oninput=e=>{critical=+e.target.value;if(critical<=warning){warning=critical-1;$('warningThreshold').value=warning}render()};$('exportBtn').onclick=()=>download('strata-telemetry.csv',C.toCSV(servers),'text/csv');$('sampleBtn').onclick=()=>download('strata-sample.csv',C.toCSV(C.makeDemo()),'text/csv');$('savePlan').onclick=()=>download('strata-scenario.json',JSON.stringify({server:current().name,source:current().source,scenario:scenario(),beforeDays:C.runway(current(),90),afterDays:C.runway(current(),90,current().capacity+scenario().add,scenario().reclaim,scenario().factor),note:'What-if plan only. No infrastructure change.'},null,2),'application/json');$('advanceBtn').onclick=()=>{if(!servers.every(s=>s.source==='Synthetic'))return;for(const s of servers){const last=s.points.at(-1),slope=C.fit(s.points).slope;s.points.push({day:last.day+1,used:+Math.min(s.capacity,Math.max(0,last.used+slope+Math.sin(last.day*1.7)*slope*.6)).toFixed(2)})}render();toast('One synthetic day added. Models and alerts recalculated.')};$('resetBtn').onclick=()=>{servers=C.makeDemo();selected=servers[0].id;warning=80;critical=90;acknowledged.clear();$('warningThreshold').value=80;$('criticalThreshold').value=90;updateSelects();render();toast('Original demonstration restored')};$('importBtn').onclick=()=>$('csvInput').click();$('csvInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Import a CSV under 5 MB.');const next=C.parseCSV(await file.text());servers=next;selected=servers[0].id;acknowledged.clear();updateSelects();render();toast(`Imported ${servers.length} servers. Models recalculated.`)}catch(err){toast(err.message)}e.target.value=''};$('openAdvisor').onclick=()=>$('advisorDialog').showModal();$('advisorForm').onsubmit=e=>{e.preventDefault();ask($('question').value)};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>ask(b.dataset.question));document.querySelectorAll('.closeDialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('collectorHelpBtn').onclick=()=>{$('collectorHelp').hidden=!$('collectorHelp').hidden};$('folderBtn').onclick=()=>$('folderInput').click();$('folderInput').onchange=e=>{const files=[...e.target.files];if(!files.length)return;const size=files.reduce((s,f)=>s+f.size,0),top=files.sort((a,b)=>b.size-a.size).slice(0,8);$('folderResult').hidden=false;$('folderResult').innerHTML=`<div class="eyebrow">REAL LOCAL FILE METADATA</div><h2 style="margin:12px 0">${files.length} files · ${bytes(size)}</h2><p>Measured from your selected folder. No file contents are uploaded or read. This is folder inventory, not total disk capacity or a historical forecast.</p><div class="tablewrap"><table><thead><tr><th>Largest files</th><th>Logical size</th></tr></thead><tbody>${top.map(f=>`<tr><td>${esc(f.webkitRelativePath||f.name)}</td><td>${bytes(f.size)}</td></tr>`).join('')}</tbody></table></div>`;toast('Local folder measured. No upload performed.');e.target.value=''};$('tourBtn').onclick=()=>{tourStep=0;showTour()};$('tourBack').onclick=()=>{tourStep=Math.max(0,tourStep-1);showTour()};$('tourNext').onclick=()=>{if(tourStep===4)$('tourDialog').close();else{tourStep++;showTour()}};render();
